using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Reflection;using System.Threading;using System.Windows;using System.Windows.Controls;using System.Windows.Controls.Primitives;
namespace FileCompass {
 public partial class FilePanel {
  internal void VerifyRecycleMenu(Action<bool,string> check)
  {
   ShowFileContextMenu(false);
   NavigationTests.Wait(System.Threading.Tasks.Task.Delay(60));
   check(IsRecycleBin && recycleMenu != null && recycleMenu.IsOpen, "The Recycle Bin opens its own commands even when empty");
   var commands = recycleMenu.Items.OfType<MenuItem>().ToArray();
   check(commands.Select(item => item.Tag).SequenceEqual(new[] { "recycle.restore", "recycle.empty" }), "The Recycle Bin offers restore and empty commands");
   check(commands[0].IsEnabled == (RecycleSelection().Length > 0), "Restore is offered only when a Recycle Bin item is selected");
   check(Selected().Count == 0, "Recycle Bin identities are excluded from ordinary file operations");
   recycleMenu.IsOpen = false;

   var originalRows = List.ItemsSource;
   var item = new Entry
   {
    Name = "deleted-photo.jpg",
    RecycleId = @"C:\$Recycle.Bin\test\$R1.jpg",
    FullPath = @"recycle-item:C:\$Recycle.Bin\test\$R1.jpg"
   };
   try
   {
    List.ItemsSource = new[] { item };
    List.SelectedItem = item;
    check(RecycleSelection().SequenceEqual(new[] { item.RecycleId }), "Restore receives the shell identity of the selected deleted file");
    var owner = (MainWindow)Window.GetWindow(this);
    var preview = owner.PreviewInOtherPanel(this);
    check(preview.SelectionCount == 0 && preview.LoadingTask == null, "A populated Recycle Bin never passes virtual item paths to file preview");
    owner.CloseQuickPreview();
    UpdateDriveSelection();
    check(driveSelector.SelectedItem == null && IsRecycleBin, "Drive refresh does not resolve the Recycle Bin identifier to a disk path");
   }
   finally { List.ItemsSource = originalRows; }
  }
  internal void VerifyRightCapture(Entry entry,Action<bool,string> check){
   MarkAll(false);RightPressedForTests=()=>true;RightPositionForTests=()=>new Point(20,80);BeginContextEntry(entry,new Point(20,80));System.Windows.Input.Mouse.Capture(List,System.Windows.Input.CaptureMode.SubTree);
   check(contextPending,"Right press remains pending regardless of capture availability");
   List.RaiseEvent(new System.Windows.Input.MouseEventArgs(System.Windows.Input.Mouse.PrimaryDevice,Environment.TickCount){RoutedEvent=System.Windows.Input.Mouse.LostMouseCaptureEvent});
   NavigationTests.Wait(System.Threading.Tasks.Task.Delay(30));check(contextPending,"Bubbling capture notification does not cancel a captured right press");
   FinishContextEntry(TimeSpan.FromMilliseconds(100));check(entry.IsMarked,"Short right click marks after capture notification and release");RightPressedForTests=null;RightPositionForTests=null;
  }
 }
